// --- sign: identical in every LendLoop workflow ---
// Same algorithm as signRequest in convex/lib/signature.ts:
//   X-LendLoop-Signature: t=<unix seconds>,v1=HMAC-SHA256(secret, `${t}.${METHOD}.${path}.${body}`)
// The HTTP Request node sends `rawBody` as a raw string, so the signed bytes are the sent bytes.
const crypto = require('crypto');
function sign(method, path, body) {
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto
    .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
    .update(`${t}.${method}.${path}.${body}`, 'utf8')
    .digest('hex');
  const base = $env.LENDLOOP_CONVEX_SITE_URL.replace(/\/$/, '');
  return { url: base + path, signature: `t=${t},v1=${v1}`, rawBody: body };
}
// --- end sign ---

// Signed GET: the body is empty, so the signed string ends with a dot.
return [{ json: sign('GET', '/automation/overdue-loans', '') }];

// Runs once every loan has been handled. Failed reminders are already recorded on their
// loans; failing the run here also sends them to the error workflow, so ops and the admin
// panel see them.
const statuses = $input.all().map((i) => i.json.status);
const failed = statuses.filter((s) => s === 'failed').length;
if (failed > 0) throw new Error(`${failed} of ${statuses.length} overdue reminders could not be sent`);
return [{ json: { sent: statuses.length } }];

// Everything a user typed (names, tool names) goes through escapeHtml before it reaches
// the HTML, so a tool called "<b>Drill</b> & Saw" shows up literally.
const escapeHtml = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// "2026-11-12" -> "Thu, 12 Nov 2026". Loan dates are UTC calendar dates.
const formatDate = (d) =>
  new Date(`${d}T00:00:00Z`).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });

// One plain layout for every LendLoop email. All arguments are plain text; this escapes them.
function layout({ greetingName, line, detail, link, cta }) {
  return [
    '<div style="font-family:system-ui,-apple-system,sans-serif;max-width:480px;margin:0 auto;color:#18181b;line-height:1.5">',
    `<p>Hi ${escapeHtml(greetingName)},</p>`,
    `<p>${escapeHtml(line)}</p>`,
    `<p style="padding:12px 16px;background:#f4f4f5;border-radius:8px">${detail.map(escapeHtml).join('<br>')}</p>`,
    `<p><a href="${escapeHtml(link)}" style="display:inline-block;padding:10px 16px;background:#18181b;color:#fff;border-radius:6px;text-decoration:none">${escapeHtml(cta)}</a></p>`,
    '<p style="color:#71717a;font-size:12px">You get this email because you use LendLoop.</p>',
    '</div>',
  ].join('\n');
}

// Builds the reminder for one overdue loan from GET /automation/overdue-loans:
// { loanId, reminderKey, borrower: { email, name }, tool: { name }, endDate, daysOverdue }
const loan = $json;
const tool = loan.tool.name;
const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
const line = `${tool} was due back on ${formatDate(loan.endDate)} (${days} ago). Please return it to its owner. If you already did, tell them from the loan page.`;
const link = `${$env.LENDLOOP_APP_URL}/loans/${encodeURIComponent(loan.loanId)}`;

return {
  json: {
    loanId: loan.loanId,
    reminderKey: loan.reminderKey,
    to: loan.borrower.email,
    subject: `Reminder: please return ${tool}`,
    html: layout({ greetingName: loan.borrower.name, line, detail: [tool, `Due ${formatDate(loan.endDate)}`], link, cta: 'Open the loan' }),
    text: `Hi ${loan.borrower.name},\n\n${line}\n\nOpen the loan: ${link}\n`,
  },
};

// --- sign: identical in every LendLoop workflow ---
// Same algorithm as signRequest in convex/lib/signature.ts:
//   X-LendLoop-Signature: t=<unix seconds>,v1=HMAC-SHA256(secret, `${t}.${METHOD}.${path}.${body}`)
// The HTTP Request node sends `rawBody` as a raw string, so the signed bytes are the sent bytes.
const crypto = require('crypto');
function sign(method, path, body) {
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto
    .createHmac('sha256', $env.N8N_TO_CONVEX_SECRET)
    .update(`${t}.${method}.${path}.${body}`, 'utf8')
    .digest('hex');
  const base = $env.LENDLOOP_CONVEX_SITE_URL.replace(/\/$/, '');
  return { url: base + path, signature: `t=${t},v1=${v1}`, rawBody: body };
}
// --- end sign ---

// Record the reminder outcome. Convex upserts by reminderKey (`${loanId}:${today}`), so a
// re-run records nothing new, and a failed reminder can later be upgraded to sent.
const { loanId, reminderKey } = $('Build reminder email').item.json;
const { status } = $json; // "sent" or "failed", set by the Mark nodes
const body = JSON.stringify({ reminderKey, loanId, status, executionId: $execution.id });
return { json: { ...sign('POST', '/automation/reminders', body), status } };
